import React from 'react';

function Home() {
  const containerStyle = {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 50%, #f093fb 100%)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    padding: '20px'
  };

  const contentStyle = {
    textAlign: 'center'
  };

  const titleStyle = {
    fontSize: '3rem',
    fontWeight: 'bold',
    color: 'white',
    marginBottom: '15px'
  };

  const subtitleStyle = {
    fontSize: '1.3rem',
    color: 'rgba(255, 255, 255, 0.9)',
    marginBottom: '50px'
  };

  const buttonContainerStyle = {
    display: 'flex',
    gap: '25px',
    justifyContent: 'center',
    flexWrap: 'wrap'
  };

  const buttonStyle = {
    backgroundColor: 'white',
    color: '#764ba2',
    fontWeight: 'bold',
    fontSize: '1.2rem',
    padding: '20px 40px',
    borderRadius: '15px',
    border: 'none',
    boxShadow: '0 4px 15px rgba(0, 0, 0, 0.2)',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    transition: 'all 0.3s ease'
  };

  return (
    <div style={containerStyle}>
      <div style={contentStyle}>
        {/* Title */}
        <h1 style={titleStyle}>Inventory Management</h1>
        <p style={subtitleStyle}>Manage your items efficiently</p>
        
        {/* Buttons */}
        <div style={buttonContainerStyle}>
          <button
            onClick={() => (window.location.href = '/additem')}
            style={buttonStyle}
            onMouseOver={(e) => {
              e.currentTarget.style.transform = 'scale(1.05)';
              e.currentTarget.style.boxShadow = '0 6px 20px rgba(0, 0, 0, 0.3)';
            }}
            onMouseOut={(e) => {
              e.currentTarget.style.transform = 'scale(1)';
              e.currentTarget.style.boxShadow = '0 4px 15px rgba(0, 0, 0, 0.2)';
            }}
          >
            <span style={{ fontSize: '1.8rem' }}>➕</span>
            <span>Add Item</span>
          </button>
          
          <button
            onClick={() => (window.location.href = '/allitems')}
            style={buttonStyle}
            onMouseOver={(e) => {
              e.currentTarget.style.transform = 'scale(1.05)';
              e.currentTarget.style.boxShadow = '0 6px 20px rgba(0, 0, 0, 0.3)';
            }}
            onMouseOut={(e) => {
              e.currentTarget.style.transform = 'scale(1)';
              e.currentTarget.style.boxShadow = '0 4px 15px rgba(0, 0, 0, 0.2)';
            }}
          >
            <span style={{ fontSize: '1.8rem' }}>📋</span>
            <span>All Items</span>
          </button>

          <button
            onClick={() => (window.location.href = '/register')}
            style={buttonStyle}
            onMouseOver={(e) => {
              e.currentTarget.style.transform = 'scale(1.05)';
              e.currentTarget.style.boxShadow = '0 6px 20px rgba(0, 0, 0, 0.3)';
            }}
            onMouseOut={(e) => {
              e.currentTarget.style.transform = 'scale(1)';
              e.currentTarget.style.boxShadow = '0 4px 15px rgba(0, 0, 0, 0.2)';
            }}
          >
            <span style={{ fontSize: '1.8rem' }}>👤</span>
            <span>Register</span>
          </button>

          <button
            onClick={() => (window.location.href = '/login')}
            style={buttonStyle}
            onMouseOver={(e) => {
              e.currentTarget.style.transform = 'scale(1.05)';
              e.currentTarget.style.boxShadow = '0 6px 20px rgba(0, 0, 0, 0.3)';
            }}
            onMouseOut={(e) => {
              e.currentTarget.style.transform = 'scale(1)';
              e.currentTarget.style.boxShadow = '0 4px 15px rgba(0, 0, 0, 0.2)';
            }}
          >
            <span style={{ fontSize: '1.8rem' }}>👤</span>
            <span>Logi</span>
          </button>

        </div>
      </div>
    </div>
  );
}

export default Home;
